B.ah5=s(["1 lomo de salm\xf3n (descongelado la noche antes)","1 patata grande","1 cucharadita de aceite de oliva","Sal","Opcional: lim\xf3n"],t.s)
B.atE=s(["Precalienta el horno a 200 \xb0C.","Lava la patata, c\xf3rtala en gajos, ponle aceite y sal y horn\xe9ala 25 minutos.","A\xf1ade el salm\xf3n a la bandeja con sal y aceite y hornea 12-15 minutos m\xe1s.","Est\xe1 hecho cuando se separa en l\xe1minas con el tenedor."],t.s)
B.aKw=new A.aU("salmon-patata","Salm\xf3n al horno con patata asada",40,"1 raci\xf3n",B.ah5,B.atE,"Para ir m\xe1s r\xe1pido: pincha la patata y dale 8 minutos de microondas antes de hornearla.",560,36,B.U,B.fQ,!1)
B.ana=s(["90 g de espaguetis","40 g de bacon","1 huevo + 1 yema","20 g de queso rallado","Pimienta","Sal"],t.s)
B.ai9=s(["Cuece la pasta en agua con sal.","Dora el bacon en taquitos en una sart\xe9n sin aceite, 4 minutos.","Bate el huevo, la yema y el queso con pimienta.","Escurre la pasta guardando medio vaso del agua de cocerla.","Fuera del fuego, mezcla la pasta con el bacon y a\xf1ade el huevo removiendo r\xe1pido, con un poco del agua, hasta que quede cremoso."],t.s)
B.aKe=new A.aU("carbonara","Espaguetis carbonara",15,"1 raci\xf3n",B.ana,B.ai9,"Siempre fuera del fuego: si no, el huevo se cuaja y queda como un revuelto.",640,29,B.U,B.cd,!1)
