B.azB=s(["1 caf\xe9 (de cafetera, c\xe1psula o soluble)","200 ml de leche entera","Az\xfacar o edulcorante al gusto"],t.s)
B.aie=s(["Prepara el caf\xe9 en la cafetera o con la c\xe1psula.","Calienta la leche en el microondas 1 minuto y medio (o en un cazo sin que llegue a hervir).","M\xe9zclalos en una taza grande y a\xf1ade el az\xfacar si lo tomas."],t.s)
B.aKY=new A.aU("cafe-con-leche","Caf\xe9 con leche",5,"1 taza",B.azB,B.aie,"Para ganar peso, usa leche entera y t\xf3malo con unas tostadas: tostadas con aceite + caf\xe9 con leche son unas 490 kcal.",130,7,B.ct,B.cs,!1)
B.azj=s(["150 g de fresas (frescas o congeladas)","1 yogur griego","250 ml de leche","40 g de copos de avena","1 cucharadita de miel"],t.s)
B.amK=s(["Echa todo en la batidora.","Bate 1 minuto hasta que quede fino."],t.s)
B.aKZ=new A.aU("batido-fresa-avena","Batido de fresa, avena y yogur",3,"1 raci\xf3n",B.azj,B.amK,null,510,19,B.dL,B.eg,!1)
B.ah_=s(["1 bote de garbanzos cocidos (400 g)","1 cucharada de tahini (o 2 de aceite m\xe1s)","1 diente de ajo","Zumo de \xbd lim\xf3n","3 cucharadas de aceite de oliva","Comino, piment\xf3n y sal","2 panes de pita o zanahoria en bastones"],t.s)
B.adX=s(["Lava los garbanzos y guarda un poco del l\xedquido del bote.","Trit\xfaralos con el tahini, el ajo, el lim\xf3n, el aceite, el comino y sal.","A\xf1ade un chorrito del l\xedquido hasta que quede cremoso.","Sirve con piment\xf3n y un chorro de aceite, con el pan de pita."],t.s)
B.aKh=new A.aU("hummus","Hummus con pan de pita",10,"2 raciones",B.ah_,B.adX,"Aguanta 4 d\xedas en la nevera: un tentempi\xe9 listo para toda la semana.",580,20,B.dL,B.eg,!1)
